use vstd::prelude::*;

verus! {

fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
    ensures
        // Length is doubled
        result@.len() == 2 * arr@.len(),
        // Interleaving property: [elem, arr[0], elem, arr[1], ...]
        forall|k: int|
            0 <= k < arr@.len() ==> (
                result@[2 * k] == elem
                && result@[2 * k + 1] == arr@[k]
            )
{
    let mut result: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < arr.len()
        invariant
            i <= arr.len(),
            result@.len() == 2 * i as int,
            forall|k: int|
                0 <= k < i as int ==> (
                    result@[2 * k] == elem
                    && result@[2 * k + 1] == arr@[k]
                )
    {
        result.push(elem);
        result.push(arr[i]);
        i += 1;
    }

    result
}

} // verus!